import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum InterestType {
  FIXED = 'FIXED',
  REDUCING = 'REDUCING'
}

export enum CalculationGoal {
  INSTALLMENT = 'INSTALLMENT',
  LOAN_AMOUNT = 'LOAN_AMOUNT'
}

export interface LoanInputs {
  principal: number;
  interestRate: number;
  termMonths: number;
  interestType: InterestType;
  goal: CalculationGoal;
  targetInstallment: number;
  currency: string;
}

export interface AmortizationRow {
  month: number;
  payment: number;
  principal: number;
  interest: number;
  remainingBalance: number;
}

export interface LoanResults {
  monthlyPayment: number;
  totalPrincipal: number;
  totalInterest: number;
  totalPayment: number;
  amortizationSchedule: AmortizationRow[];
}

import { LoanInputs, LoanResults, InterestType, CalculationGoal, AmortizationRow } from './types';

export const formatCurrency = (value: number, currency: string = 'USD') => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
    maximumFractionDigits: 0,
  }).format(value);
};

export const calculateLoan = (inputs: LoanInputs): LoanResults => {
  const { interestRate, termMonths, interestType, goal, targetInstallment } = inputs;
  const monthlyRate = interestRate / 100 / 12;

  let principal = inputs.principal;
  let monthlyPayment = 0;

  if (goal === CalculationGoal.LOAN_AMOUNT) {
    // Reverse calculation: Find principal based on target installment
    if (interestType === InterestType.REDUCING) {
      // P = (PMT / i) * [1 - (1 + i)^-n]
      principal = (targetInstallment / monthlyRate) * (1 - Math.pow(1 + monthlyRate, -termMonths));
    } else {
      // PMT = (Principal + TotalInterest) / n
      // PMT = (Principal + Principal * yearlyRate * years) / n
      // Principal = (PMT * n) / (1 + yearlyRate * years)
      const yearlyRate = interestRate / 100;
      const years = termMonths / 12;
      principal = (targetInstallment * termMonths) / (1 + (yearlyRate * years));
    }
    monthlyPayment = targetInstallment;
  } else {
    // Standard calculation: Find installment based on principal
    if (interestType === InterestType.REDUCING) {
      // PMT = P * [i(1+i)^n] / [(1+i)^n - 1]
      monthlyPayment = (principal * monthlyRate * Math.pow(1 + monthlyRate, termMonths)) / (Math.pow(1 + monthlyRate, termMonths) - 1);
    } else {
      // Fixed: Total Interest = Principal * Rate * Years
      const totalInterest = principal * (interestRate / 100) * (termMonths / 12);
      monthlyPayment = (principal + totalInterest) / termMonths;
    }
  }

  const schedule: AmortizationRow[] = [];
  let currentBalance = principal;
  let totalInterestAccumulated = 0;

  for (let m = 1; m <= termMonths; m++) {
    let interestPortion = 0;
    let principalPortion = 0;

    if (interestType === InterestType.REDUCING) {
      interestPortion = currentBalance * monthlyRate;
      principalPortion = monthlyPayment - interestPortion;
    } else {
      // Fixed: Monthly interest is constant
      interestPortion = (principal * (interestRate / 100) * (termMonths / 12)) / termMonths;
      principalPortion = monthlyPayment - interestPortion;
    }

    currentBalance -= principalPortion;
    if (currentBalance < 0) currentBalance = 0;

    totalInterestAccumulated += interestPortion;

    schedule.push({
      month: m,
      payment: monthlyPayment,
      principal: principalPortion,
      interest: interestPortion,
      remainingBalance: currentBalance
    });
  }

  return {
    monthlyPayment,
    totalPrincipal: principal,
    totalInterest: totalInterestAccumulated,
    totalPayment: principal + totalInterestAccumulated,
    amortizationSchedule: schedule
  };
};

import React, { useState, useMemo } from 'react';
import { 
  Calculator, 
  TrendingDown, 
  CircleDollarSign, 
  CalendarDays, 
  BarChart3, 
  BrainCircuit, 
  TableProperties,
  ArrowRightLeft,
  ChevronRight,
  ChevronDown
} from 'lucide-react';
import { LoanInputs, InterestType, CalculationGoal, LoanResults } from './types';
import { calculateLoan, formatCurrency } from './utils';
import SummaryCards from './components/SummaryCards';
import Visualizations from './components/Visualizations';
import AmortizationTable from './components/AmortizationTable';
import AIAdvisor from './components/AIAdvisor';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<LoanInputs>({
    principal: 250000,
    interestRate: 6.5,
    termMonths: 360,
    interestType: InterestType.REDUCING,
    goal: CalculationGoal.INSTALLMENT,
    targetInstallment: 1500,
    currency: 'USD'
  });

  const [activeTab, setActiveTab] = useState<'charts' | 'table'>('charts');

  const results = useMemo(() => calculateLoan(inputs), [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setInputs(prev => ({
      ...prev,
      [name]: name === 'interestType' || name === 'goal' || name === 'currency' ? value : parseFloat(value) || 0
    }));
  };

  return (
    <div className="min-h-screen pb-12">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white">
              <Calculator size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">LendSmart AI</h1>
          </div>
          <div className="hidden md:flex items-center gap-4 text-sm font-medium text-slate-500">
            <span>Powered by Gemini 3</span>
            <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Sidebar - Controls */}
        <section className="lg:col-span-4 flex flex-col gap-6">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
            <h2 className="text-lg font-semibold mb-6 flex items-center gap-2">
              <CircleDollarSign size={20} className="text-indigo-600" />
              Configure Loan
            </h2>

            <div className="space-y-5">
              {/* Goal Selector */}
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Calculation Goal</label>
                <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 rounded-lg">
                  <button
                    onClick={() => setInputs(p => ({ ...p, goal: CalculationGoal.INSTALLMENT }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-md transition-all ${inputs.goal === CalculationGoal.INSTALLMENT ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    Calculate Payment
                  </button>
                  <button
                    onClick={() => setInputs(p => ({ ...p, goal: CalculationGoal.LOAN_AMOUNT }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-md transition-all ${inputs.goal === CalculationGoal.LOAN_AMOUNT ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    Find Loan Amount
                  </button>
                </div>
              </div>

              {/* Dynamic Principal/Installment Input */}
              {inputs.goal === CalculationGoal.INSTALLMENT ? (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Loan Amount</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">$</span>
                    <input
                      type="number"
                      name="principal"
                      value={inputs.principal}
                      onChange={handleInputChange}
                      className="w-full pl-8 pr-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    />
                  </div>
                </div>
              ) : (
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Target Monthly Payment</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">$</span>
                    <input
                      type="number"
                      name="targetInstallment"
                      value={inputs.targetInstallment}
                      onChange={handleInputChange}
                      className="w-full pl-8 pr-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    />
                  </div>
                </div>
              )}

              {/* Interest Rate */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Annual Interest Rate (%)</label>
                <div className="relative">
                  <input
                    type="number"
                    step="0.1"
                    name="interestRate"
                    value={inputs.interestRate}
                    onChange={handleInputChange}
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                  />
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">%</span>
                </div>
              </div>

              {/* Term */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Loan Term (Months)</label>
                <div className="relative">
                  <input
                    type="number"
                    name="termMonths"
                    value={inputs.termMonths}
                    onChange={handleInputChange}
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                  />
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">{(inputs.termMonths / 12).toFixed(1)} yrs</span>
                </div>
              </div>

              {/* Interest Type */}
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Interest Method</label>
                <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 rounded-lg">
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.REDUCING }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-md flex items-center justify-center gap-1 transition-all ${inputs.interestType === InterestType.REDUCING ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <TrendingDown size={14} /> Reducing
                  </button>
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.FIXED }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-md flex items-center justify-center gap-1 transition-all ${inputs.interestType === InterestType.FIXED ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <ArrowRightLeft size={14} /> Fixed
                  </button>
                </div>
                <p className="mt-2 text-[10px] text-slate-400 leading-tight">
                  {inputs.interestType === InterestType.REDUCING 
                    ? "Interest is calculated based on the outstanding balance each month." 
                    : "Interest is calculated on the initial principal and remains constant."}
                </p>
              </div>
            </div>
          </div>

          <AIAdvisor inputs={inputs} results={results} />
        </section>

        {/* Content Area */}
        <section className="lg:col-span-8 space-y-8">
          {/* Summary */}
          <SummaryCards results={results} currency={inputs.currency} />

          {/* Main Visualization & Schedule */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="flex border-b border-slate-100">
              <button
                onClick={() => setActiveTab('charts')}
                className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-all ${activeTab === 'charts' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 bg-slate-50/50'}`}
              >
                <BarChart3 size={18} /> Analysis & Charts
              </button>
              <button
                onClick={() => setActiveTab('table')}
                className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-all ${activeTab === 'table' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 bg-slate-50/50'}`}
              >
                <TableProperties size={18} /> Amortization Schedule
              </button>
            </div>

            <div className="p-6">
              {activeTab === 'charts' ? (
                <Visualizations results={results} currency={inputs.currency} />
              ) : (
                <AmortizationTable schedule={results.amortizationSchedule} currency={inputs.currency} />
              )}
            </div>
          </div>
        </section>
      </main>

      {/* Persistent Mobile CTA - Optional, since it's an interactive app */}
    </div>
  );
};

export default App;

import React from 'react';
import { LoanResults } from '../types';
import { formatCurrency } from '../utils';
import { Wallet, Landmark, HandCoins, Info } from 'lucide-react';

interface SummaryCardsProps {
  results: LoanResults;
  currency: string;
}

const SummaryCards: React.FC<SummaryCardsProps> = ({ results, currency }) => {
  const cards = [
    {
      title: 'Monthly Installment',
      value: formatCurrency(results.monthlyPayment, currency),
      icon: <Wallet className="text-indigo-600" />,
      color: 'bg-indigo-50',
      description: 'The amount you pay every month.'
    },
    {
      title: 'Loan Principal',
      value: formatCurrency(results.totalPrincipal, currency),
      icon: <Landmark className="text-emerald-600" />,
      color: 'bg-emerald-50',
      description: 'The actual borrowed amount.'
    },
    {
      title: 'Total Interest',
      value: formatCurrency(results.totalInterest, currency),
      icon: <Info className="text-amber-600" />,
      color: 'bg-amber-50',
      description: 'Cost of borrowing over the term.'
    },
    {
      title: 'Total Repayment',
      value: formatCurrency(results.totalPayment, currency),
      icon: <HandCoins className="text-blue-600" />,
      color: 'bg-blue-50',
      description: 'Principal + Interest combined.'
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
      {cards.map((card, idx) => (
        <div key={idx} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between">
          <div className="flex justify-between items-start mb-4">
            <div className={`w-10 h-10 rounded-xl ${card.color} flex items-center justify-center`}>
              {card.icon}
            </div>
          </div>
          <div>
            <p className="text-sm font-medium text-slate-500">{card.title}</p>
            <h3 className="text-2xl font-bold text-slate-900 mt-1">{card.value}</h3>
          </div>
          <p className="text-[10px] text-slate-400 mt-3 leading-tight">{card.description}</p>
        </div>
      ))}
    </div>
  );
};

export default SummaryCards;

import React from 'react';
import { 
  PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip,
  AreaChart, Area, XAxis, YAxis, CartesianGrid
} from 'recharts';
import { LoanResults } from '../types';
import { formatCurrency } from '../utils';

interface VisualizationsProps {
  results: LoanResults;
  currency: string;
}

const Visualizations: React.FC<VisualizationsProps> = ({ results, currency }) => {
  const pieData = [
    { name: 'Principal', value: results.totalPrincipal, color: '#4f46e5' },
    { name: 'Interest', value: results.totalInterest, color: '#f59e0b' }
  ];

  // Downsample data for the balance chart if the term is very long
  const chartData = results.amortizationSchedule.filter((_, idx) => {
    if (results.amortizationSchedule.length <= 60) return true;
    return idx % Math.ceil(results.amortizationSchedule.length / 60) === 0;
  }).map(row => ({
    month: row.month,
    balance: Math.round(row.remainingBalance),
    paid: Math.round(results.totalPrincipal - row.remainingBalance)
  }));

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      {/* Pie Chart */}
      <div className="flex flex-col h-[350px]">
        <h3 className="text-sm font-semibold text-slate-700 mb-4">Repayment Composition</h3>
        <div className="flex-1 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip 
                formatter={(value: number) => formatCurrency(value, currency)}
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Legend verticalAlign="bottom" height={36} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Balance Over Time */}
      <div className="flex flex-col h-[350px]">
        <h3 className="text-sm font-semibold text-slate-700 mb-4">Loan Balance Evolution</h3>
        <div className="flex-1 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorBalance" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                  <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="month" 
                tick={{fontSize: 10}} 
                tickLine={false} 
                axisLine={false}
                label={{ value: 'Month', position: 'insideBottom', offset: -5, fontSize: 10 }}
              />
              <YAxis 
                tick={{fontSize: 10}} 
                tickFormatter={(val) => `$${val/1000}k`}
                tickLine={false} 
                axisLine={false}
              />
              <Tooltip 
                formatter={(value: number) => formatCurrency(value, currency)}
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Area 
                type="monotone" 
                dataKey="balance" 
                stroke="#4f46e5" 
                fillOpacity={1} 
                fill="url(#colorBalance)" 
                strokeWidth={2}
                name="Remaining Balance"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Visualizations;

import React, { useState } from 'react';
import { AmortizationRow } from '../types';
import { formatCurrency } from '../utils';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface AmortizationTableProps {
  schedule: AmortizationRow[];
  currency: string;
}

const AmortizationTable: React.FC<AmortizationTableProps> = ({ schedule, currency }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 12; // Show one year per page

  const totalPages = Math.ceil(schedule.length / rowsPerPage);
  const currentRows = schedule.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage);

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm text-left">
        <thead className="text-xs text-slate-500 uppercase bg-slate-50/50">
          <tr>
            <th className="px-4 py-3 font-semibold">Month</th>
            <th className="px-4 py-3 font-semibold">Installment</th>
            <th className="px-4 py-3 font-semibold">Principal</th>
            <th className="px-4 py-3 font-semibold">Interest</th>
            <th className="px-4 py-3 font-semibold">Remaining</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {currentRows.map((row) => (
            <tr key={row.month} className="hover:bg-slate-50 transition-colors">
              <td className="px-4 py-3 font-medium text-slate-700">{row.month}</td>
              <td className="px-4 py-3 text-slate-600">{formatCurrency(row.payment, currency)}</td>
              <td className="px-4 py-3 text-emerald-600 font-medium">{formatCurrency(row.principal, currency)}</td>
              <td className="px-4 py-3 text-amber-600 font-medium">{formatCurrency(row.interest, currency)}</td>
              <td className="px-4 py-3 text-slate-900 font-bold">{formatCurrency(row.remainingBalance, currency)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="flex items-center justify-between mt-6 px-4">
        <p className="text-xs text-slate-400">
          Showing Year {currentPage} of {Math.ceil(totalPages)}
        </p>
        <div className="flex gap-2">
          <button
            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
            disabled={currentPage === 1}
            className="p-1 rounded-md border border-slate-200 disabled:opacity-30 hover:bg-slate-50 transition-all"
          >
            <ChevronLeft size={16} />
          </button>
          <button
            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
            disabled={currentPage === totalPages}
            className="p-1 rounded-md border border-slate-200 disabled:opacity-30 hover:bg-slate-50 transition-all"
          >
            <ChevronRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default AmortizationTable;

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { LoanInputs, LoanResults } from '../types';
import { BrainCircuit, Sparkles, Loader2, RefreshCw } from 'lucide-react';

interface AIAdvisorProps {
  inputs: LoanInputs;
  results: LoanResults;
}

const AIAdvisor: React.FC<AIAdvisorProps> = ({ inputs, results }) => {
  const [advice, setAdvice] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const getAdvice = async () => {
    setLoading(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        Act as a professional senior financial advisor.
        I have a loan with the following details:
        - Principal: ${results.totalPrincipal} ${inputs.currency}
        - Annual Interest Rate: ${inputs.interestRate}%
        - Term: ${inputs.termMonths} months (${(inputs.termMonths/12).toFixed(1)} years)
        - Monthly Installment: ${results.monthlyPayment.toFixed(2)} ${inputs.currency}
        - Total Interest: ${results.totalInterest.toFixed(2)} ${inputs.currency}
        - Interest Method: ${inputs.interestType}

        Provide a concise, professional analysis (max 150 words) including:
        1. A brief "Verdict" (Is this a high or low interest environment for this loan?).
        2. One clear "Optimization Tip" (e.g., how to save interest or shorten the term).
        3. A "Risk Alert" if any aspects of the loan seem unfavorable.
        Use Markdown formatting. Be direct and helpful.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setAdvice(response.text || "No advice available at the moment.");
    } catch (err: any) {
      console.error(err);
      setError("Unable to reach the AI advisor. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Only fetch automatically on first load to save tokens, then allow manual refresh
    getAdvice();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="bg-slate-900 rounded-2xl shadow-xl p-6 text-white overflow-hidden relative border border-slate-800">
      <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
        <Sparkles size={120} />
      </div>

