import React, { useState } from 'react';
import { AmortizationRow, Language } from '../types';
import { formatCurrency } from '../utils';
import { translations } from '../translations';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface AmortizationTableProps {
  schedule: AmortizationRow[];
  currency: string;
  lang: Language;
}

const AmortizationTable: React.FC<AmortizationTableProps> = ({ schedule, currency, lang }) => {
  const t = translations[lang];
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 12; 

  const totalPages = Math.ceil(schedule.length / rowsPerPage);
  const currentRows = schedule.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage);

  const isRTL = lang === Language.AR;

  return (
    <div className="overflow-x-auto">
      <table className={`w-full text-sm ${isRTL ? 'text-right' : 'text-left'}`}>
        <thead className="text-xs text-slate-500 uppercase bg-slate-50/50">
          <tr>
            <th className="px-4 py-3 font-semibold">{t.month}</th>
            <th className="px-4 py-3 font-semibold">{t.monthlyInstallment}</th>
            <th className="px-4 py-3 font-semibold">{t.principal}</th>
            <th className="px-4 py-3 font-semibold">{t.interest}</th>
            <th className="px-4 py-3 font-semibold">{t.remaining}</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {currentRows.map((row) => (
            <tr key={row.month} className="hover:bg-slate-50 transition-colors text-[13px]">
              <td className="px-4 py-3 font-medium text-slate-700">{row.month}</td>
              <td className="px-4 py-3 text-slate-600">{formatCurrency(row.payment, currency, lang)}</td>
              <td className="px-4 py-3 text-emerald-600 font-medium">{formatCurrency(row.principal, currency, lang)}</td>
              <td className="px-4 py-3 text-amber-600 font-medium">{formatCurrency(row.interest, currency, lang)}</td>
              <td className="px-4 py-3 text-slate-900 font-bold">{formatCurrency(row.remainingBalance, currency, lang)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className={`flex items-center justify-between mt-6 px-4 ${isRTL ? 'flex-row-reverse' : ''}`}>
        <p className="text-xs text-slate-400">
          {t.showingYear} {currentPage} {t.of} {Math.ceil(totalPages)}
        </p>
        <div className={`flex gap-2 ${isRTL ? 'flex-row-reverse' : ''}`}>
          <button
            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
            disabled={currentPage === 1}
            className="p-1 rounded-md border border-slate-200 disabled:opacity-30 hover:bg-slate-50 transition-all"
          >
            {isRTL ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
          </button>
          <button
            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
            disabled={currentPage === totalPages}
            className="p-1 rounded-md border border-slate-200 disabled:opacity-30 hover:bg-slate-50 transition-all"
          >
            {isRTL ? <ChevronLeft size={16} /> : <ChevronRight size={16} />}
          </button>
        </div>
      </div>
    </div>
  );
};

