export enum InterestType {
  FIXED = 'FIXED',
  REDUCING = 'REDUCING'
}

export enum CalculationGoal {
  INSTALLMENT = 'INSTALLMENT',
  LOAN_AMOUNT = 'LOAN_AMOUNT'
}

export enum Language {
  EN = 'en',
  AR = 'ar'
}

export interface LoanInputs {
  principal: number;
  interestRate: number;
  termMonths: number;
  interestType: InterestType;
  goal: CalculationGoal;
  targetInstallment: number;
  currency: string;
  extraPayment: number;
  startDate: string;
}

export interface AmortizationRow {
  month: number;
  date: string;
  payment: number;
  extraPayment: number;
  principal: number;
  interest: number;
  remainingBalance: number;
}

export interface LoanResults {
  monthlyPayment: number;
  totalPrincipal: number;
  totalInterest: number;
  totalPayment: number;
  amortizationSchedule: AmortizationRow[];
  interestSaved: number;
  monthsSaved: number;
  actualTerm: number;
}

import { LoanInputs, LoanResults, InterestType, CalculationGoal, AmortizationRow, Language } from './types';

export const formatCurrency = (value: number, currency: string = '', lang: Language = Language.EN) => {
  try {
    if (currency.length === 3 && /^[A-Z]{3}$/i.test(currency)) {
      return new Intl.NumberFormat(lang === Language.AR ? 'ar-SA' : 'en-US', {
        style: 'currency',
        currency: currency.toUpperCase(),
        maximumFractionDigits: 0,
      }).format(value);
    }
  } catch (e) {}

  const formattedNumber = new Intl.NumberFormat(lang === Language.AR ? 'ar-SA' : 'en-US', {
    maximumFractionDigits: 0,
  }).format(value);

  return lang === Language.AR 
    ? `${formattedNumber} ${currency}`.trim()
    : `${currency} ${formattedNumber}`.trim();
};

export const calculateLoan = (inputs: LoanInputs): LoanResults => {
  const { interestRate, termMonths, interestType, goal, targetInstallment, extraPayment, startDate } = inputs;
  const monthlyRate = interestRate / 100 / 12;

  let principal = inputs.principal;
  let monthlyPayment = 0;

  // 1. Calculate the base installment
  if (goal === CalculationGoal.LOAN_AMOUNT) {
    if (interestType === InterestType.REDUCING) {
      principal = monthlyRate > 0 
        ? (targetInstallment / monthlyRate) * (1 - Math.pow(1 + monthlyRate, -termMonths))
        : targetInstallment * termMonths;
    } else {
      const yearlyRate = interestRate / 100;
      const years = termMonths / 12;
      principal = (targetInstallment * termMonths) / (1 + (yearlyRate * years));
    }
    monthlyPayment = targetInstallment;
  } else {
    if (interestType === InterestType.REDUCING) {
      monthlyPayment = monthlyRate > 0 
        ? (principal * monthlyRate * Math.pow(1 + monthlyRate, termMonths)) / (Math.pow(1 + monthlyRate, termMonths) - 1)
        : principal / termMonths;
    } else {
      const totalInterest = principal * (interestRate / 100) * (termMonths / 12);
      monthlyPayment = (principal + totalInterest) / termMonths;
    }
  }

  // 2. Generate Schedule with Extra Payments
  const schedule: AmortizationRow[] = [];
  let currentBalance = principal;
  let totalInterestAccumulated = 0;
  let baseInterestAccumulated = 0;

  const start = startDate ? new Date(startDate) : new Date();

  for (let m = 1; m <= termMonths && currentBalance > 0.01; m++) {
    let interestPortion = 0;

    if (interestType === InterestType.REDUCING) {
      interestPortion = currentBalance * monthlyRate;
    } else {
      interestPortion = (principal * (interestRate / 100) * (termMonths / 12)) / termMonths;
    }

    let principalPortion = monthlyPayment - interestPortion;

    // Check if we're paying more than the balance
    if (principalPortion > currentBalance) {
      principalPortion = currentBalance;
    }

    currentBalance -= principalPortion;

    // Apply extra payment
    let appliedExtra = 0;
    if (currentBalance > 0) {
      appliedExtra = Math.min(extraPayment, currentBalance);
      currentBalance -= appliedExtra;
    }

    totalInterestAccumulated += interestPortion;

    const rowDate = new Date(start);
    rowDate.setMonth(start.getMonth() + m - 1);

    schedule.push({
      month: m,
      date: rowDate.toLocaleDateString('default', { month: 'short', year: 'numeric' }),
      payment: principalPortion + interestPortion,
      extraPayment: appliedExtra,
      principal: principalPortion,
      interest: interestPortion,
      remainingBalance: Math.max(0, currentBalance)
    });
  }

  // 3. Comparison for "Savings" Metrics
  // We approximate the base total interest by assuming 0 extra payments over full term
  const baseTotalInterest = (monthlyPayment * termMonths) - principal;

  return {
    monthlyPayment,
    totalPrincipal: principal,
    totalInterest: totalInterestAccumulated,
    totalPayment: principal + totalInterestAccumulated,
    amortizationSchedule: schedule,
    interestSaved: Math.max(0, baseTotalInterest - totalInterestAccumulated),
    monthsSaved: termMonths - schedule.length,
    actualTerm: schedule.length
  };
};

export const downloadCSV = (schedule: AmortizationRow[], lang: Language, currency: string) => {
  const headers = lang === Language.EN 
    ? ["Month", "Date", "Payment", "Extra", "Principal", "Interest", "Balance"]
    : ["الشهر", "التاريخ", "الدفع", "إضافي", "الأصل", "الفائدة", "الرصيد"];

  const rows = schedule.map(r => [
    r.month,
    r.date,
    r.payment.toFixed(2),
    r.extraPayment.toFixed(2),
    r.principal.toFixed(2),
    r.interest.toFixed(2),
    r.remainingBalance.toFixed(2)
  ]);

  const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.setAttribute("href", url);
  link.setAttribute("download", `amortization_${new Date().toISOString().split('T')[0]}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

