export enum InterestType {
  FIXED = 'FIXED',
  REDUCING = 'REDUCING'
}

export enum CalculationGoal {
  INSTALLMENT = 'INSTALLMENT',
  LOAN_AMOUNT = 'LOAN_AMOUNT',
  BUY_VS_RENT = 'BUY_VS_RENT'
}

export enum Language {
  EN = 'en',
  AR = 'ar'
}

export interface LoanInputs {
  principal: number;
  interestRate: number;
  termMonths: number;
  interestType: InterestType;
  goal: CalculationGoal;
  targetInstallment: number;
  currency: string;
  // Buy vs Rent specific
  monthlyRent: number;
  rentIncrease: number;
  propertyAppreciation: number;
  maintenancePercent: number;
  investmentReturn: number;
}

export interface AmortizationRow {
  month: number;
  payment: number;
  principal: number;
  interest: number;
  remainingBalance: number;
}

export interface BuyVsRentYearly {
  year: number;
  buyingUnrecoverable: number; // Interest + Maintenance
  rentingUnrecoverable: number; // Cumulative Rent
  buyingNetWorth: number; // Equity + Appreciation - Interest - Maintenance
  rentingNetWorth: number; // Initial capital + monthly difference invested
}

export interface LoanResults {
  monthlyPayment: number;
  totalPrincipal: number;
  totalInterest: number;
  totalPayment: number;
  amortizationSchedule: AmortizationRow[];
  buyVsRentComparison?: BuyVsRentYearly[];
  breakEvenYear?: number;
}

import { LoanInputs, LoanResults, InterestType, CalculationGoal, AmortizationRow, Language, BuyVsRentYearly } from './types';

export const formatCurrency = (value: number, currency: string = '', lang: Language = Language.EN) => {
  try {
    if (currency.length === 3 && /^[A-Z]{3}$/i.test(currency)) {
      return new Intl.NumberFormat(lang === Language.AR ? 'ar-SA' : 'en-US', {
        style: 'currency',
        currency: currency.toUpperCase(),
        maximumFractionDigits: 0,
      }).format(value);
    }
  } catch (e) {}

  const formattedNumber = new Intl.NumberFormat(lang === Language.AR ? 'ar-SA' : 'en-US', {
    maximumFractionDigits: 0,
  }).format(value);

  return lang === Language.AR 
    ? `${formattedNumber} ${currency}`.trim()
    : `${currency} ${formattedNumber}`.trim();
};

export const calculateLoan = (inputs: LoanInputs): LoanResults => {
  const { 
    interestRate, termMonths, interestType, goal, targetInstallment,
    monthlyRent, rentIncrease, propertyAppreciation, maintenancePercent, investmentReturn
  } = inputs;
  const monthlyRate = interestRate / 100 / 12;

  let principal = inputs.principal;
  let monthlyPayment = 0;

  if (goal === CalculationGoal.LOAN_AMOUNT) {
    if (interestType === InterestType.REDUCING) {
      principal = monthlyRate > 0 
        ? (targetInstallment / monthlyRate) * (1 - Math.pow(1 + monthlyRate, -termMonths))
        : targetInstallment * termMonths;
    } else {
      const yearlyRate = interestRate / 100;
      const years = termMonths / 12;
      principal = (targetInstallment * termMonths) / (1 + (yearlyRate * years));
    }
    monthlyPayment = targetInstallment;
  } else {
    // Goal is either INSTALLMENT or BUY_VS_RENT
    if (interestType === InterestType.REDUCING) {
      monthlyPayment = monthlyRate > 0 
        ? (principal * monthlyRate * Math.pow(1 + monthlyRate, termMonths)) / (Math.pow(1 + monthlyRate, termMonths) - 1)
        : principal / termMonths;
    } else {
      const totalInterest = principal * (interestRate / 100) * (termMonths / 12);
      monthlyPayment = (principal + totalInterest) / termMonths;
    }
  }

  const schedule: AmortizationRow[] = [];
  let currentBalance = principal;
  let totalInterestAccumulated = 0;

  for (let m = 1; m <= termMonths; m++) {
    let interestPortion = 0;
    let principalPortion = 0;

    if (interestType === InterestType.REDUCING) {
      interestPortion = currentBalance * monthlyRate;
      principalPortion = monthlyPayment - interestPortion;
    } else {
      interestPortion = (principal * (interestRate / 100) * (termMonths / 12)) / termMonths;
      principalPortion = monthlyPayment - interestPortion;
    }

    currentBalance -= principalPortion;
    if (currentBalance < 0) currentBalance = 0;

    totalInterestAccumulated += interestPortion;

    schedule.push({
      month: m,
      payment: monthlyPayment,
      principal: principalPortion,
      interest: interestPortion,
      remainingBalance: currentBalance
    });
  }

  // Buy vs Rent Logic
  const buyVsRentComparison: BuyVsRentYearly[] = [];
  let breakEvenYear: number | undefined;

  if (goal === CalculationGoal.BUY_VS_RENT) {
    let currentPropertyVal = principal; // Assuming downpayment is 0 for simplicity of pure math comparison or principal = total value
    let buyerUnrecoverableCumulative = 0;
    let renterUnrecoverableCumulative = 0;
    let currentRent = monthlyRent;

    // Wealth tracking
    let renterWealth = 0; // Investing the "difference" if renting is cheaper
    let buyerEquity = 0;

    for (let year = 1; year <= Math.ceil(termMonths / 12); year++) {
      let yearlyInterest = 0;
      let yearlyPrincipal = 0;
      for (let m = 1; m <= 12; m++) {
        const monthIdx = (year - 1) * 12 + (m - 1);
        if (monthIdx < schedule.length) {
          yearlyInterest += schedule[monthIdx].interest;
          yearlyPrincipal += schedule[monthIdx].principal;
        }
      }

      const yearlyMaint = currentPropertyVal * (maintenancePercent / 100);
      buyerUnrecoverableCumulative += yearlyInterest + yearlyMaint;
      renterUnrecoverableCumulative += currentRent * 12;

      // Appreciation
      const appreciation = currentPropertyVal * (propertyAppreciation / 100);
      currentPropertyVal += appreciation;

      // Wealth
      buyerEquity += yearlyPrincipal;
      const buyerNetWorth = (buyerEquity + (currentPropertyVal - principal)) - (yearlyInterest + yearlyMaint); // Simplified

      // Renter Wealth (if renting is cheaper, invest the diff)
      const yearlySavings = (monthlyPayment * 12 + yearlyMaint) - (currentRent * 12);
      renterWealth = (renterWealth + Math.max(0, yearlySavings)) * (1 + investmentReturn / 100);

      buyVsRentComparison.push({
        year,
        buyingUnrecoverable: buyerUnrecoverableCumulative,
        rentingUnrecoverable: renterUnrecoverableCumulative,
        buyingNetWorth: buyerEquity + (currentPropertyVal - principal),
        rentingNetWorth: renterWealth
      });

      if (breakEvenYear === undefined && (buyerEquity + (currentPropertyVal - principal)) > renterWealth) {
        breakEvenYear = year;
      }

      currentRent *= (1 + rentIncrease / 100);
    }
  }

  return {
    monthlyPayment,
    totalPrincipal: principal,
    totalInterest: totalInterestAccumulated,
    totalPayment: principal + totalInterestAccumulated,
    amortizationSchedule: schedule,
    buyVsRentComparison,
    breakEvenYear
  };
};

