                  <button
                    onClick={() => setInputs(p => ({ ...p, goal: CalculationGoal.BUY_VS_RENT }))}
                    className={`py-2 px-1 text-[10px] font-semibold rounded-lg transition-all ${inputs.goal === CalculationGoal.BUY_VS_RENT ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}
                  >
                    {t.buyVsRent}
                  </button>
                </div>
              </div>

              {/* Core Loan Inputs */}
              <div className="space-y-4">
                <div>
