                    <Home size={14} /> Renting vs Appreciation
                  </h3>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">{t.monthlyRent}</label>
                    <input
                      type="number"
                      name="monthlyRent"
                      value={inputs.monthlyRent}
                      onChange={handleInputChange}
                      className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none dark:text-white"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-medium text-slate-500 mb-1">{t.rentIncrease}</label>
                      <input
                        type="number"
                        name="rentIncrease"
                        value={inputs.rentIncrease}
                        onChange={handleInputChange}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs dark:text-white"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-slate-500 mb-1">{t.appreciation}</label>
                      <input
                        type="number"
                        name="propertyAppreciation"
                        value={inputs.propertyAppreciation}
                        onChange={handleInputChange}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs dark:text-white"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-medium text-slate-500 mb-1">{t.maintenance}</label>
                      <input
                        type="number"
                        name="maintenancePercent"
                        value={inputs.maintenancePercent}
                        onChange={handleInputChange}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs dark:text-white"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-slate-500 mb-1">{t.investReturn}</label>
                      <input
                        type="number"
                        name="investmentReturn"
                        value={inputs.investmentReturn}
                        onChange={handleInputChange}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs dark:text-white"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* Interest Type */}
              <div>
                <label className="block text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-2">{t.interestMethod}</label>
                <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 dark:bg-slate-800 rounded-xl">
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.REDUCING }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-lg flex items-center justify-center gap-2 transition-all ${inputs.interestType === InterestType.REDUCING ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                  >
                    <TrendingDown size={14} /> {t.reducing}
                  </button>
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.FIXED }))}
                    className={`py-2 px-3 text-xs font-semibold rounded-lg flex items-center justify-center gap-2 transition-all ${inputs.interestType === InterestType.FIXED ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                  >
                    <ArrowRightLeft size={14} /> {t.fixed}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Content Area */}
        <section className="lg:col-span-8 flex flex-col gap-8">
          <SummaryCards results={results} currency={inputs.currency} lang={lang} goal={inputs.goal} />

          <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex-1">
            <div className="flex border-b border-slate-100 dark:border-slate-800">
              <button
                onClick={() => setActiveTab('charts')}
                className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-all ${activeTab === 'charts' ? 'text-indigo-600 dark:text-indigo-400 border-b-2 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-slate-900' : 'text-slate-500 dark:text-slate-400 bg-slate-50/50 dark:bg-slate-800/30'}`}
              >
                <BarChart3 size={18} /> {t.analysisCharts}
              </button>
              <button
                onClick={() => setActiveTab('table')}
                className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-all ${activeTab === 'table' ? 'text-indigo-600 dark:text-indigo-400 border-b-2 border-indigo-600 dark:border-indigo-400 bg-white dark:bg-slate-900' : 'text-slate-500 dark:text-slate-400 bg-slate-50/50 dark:bg-slate-800/30'}`}
              >
                <TableProperties size={18} /> {t.amortSchedule}
              </button>
            </div>

            <div className="p-6 h-full min-h-[500px]">
              {activeTab === 'charts' ? (
                <Visualizations 
                  results={results} 
                  currency={inputs.currency} 
                  lang={lang} 
                  isDark={isDark} 
                  goal={inputs.goal}
                />
              ) : (
                <AmortizationTable 
                  schedule={results.amortizationSchedule} 
                  currency={inputs.currency} 
                  lang={lang} 
                />
              )}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { LoanResults, Language, CalculationGoal } from '../types';
import { formatCurrency } from '../utils';
import { translations } from '../translations';
import { Wallet, Landmark, HandCoins, Info, Clock, TrendingUp, ShieldCheck } from 'lucide-react';

interface SummaryCardsProps {
  results: LoanResults;
  currency: string;
  lang: Language;
  goal: CalculationGoal;
}

const SummaryCards: React.FC<SummaryCardsProps> = ({ results, currency, lang, goal }) => {
  const t = translations[lang];

  const isBuyVsRent = goal === CalculationGoal.BUY_VS_RENT;

  const cards = isBuyVsRent ? [
    {
      title: t.monthlyInstallment,
      value: formatCurrency(results.monthlyPayment, currency, lang),
      icon: <Wallet className="text-indigo-600 dark:text-indigo-400" />,
      color: 'bg-indigo-50 dark:bg-indigo-900/20',
      description: t.installmentDesc
    },
    {
      title: t.buyVsRent,
      value: results.breakEvenYear ? `${t.betterToBuy} ${results.breakEvenYear} ${t.yrs}` : t.betterToRent,
      icon: <Clock className="text-emerald-600 dark:text-emerald-400" />,
      color: 'bg-emerald-50 dark:bg-emerald-900/20',
      description: t.rentDesc
    },
    {
      title: t.totalInterest,
      value: formatCurrency(results.totalInterest, currency, lang),
      icon: <Info className="text-amber-600 dark:text-amber-400" />,
      color: 'bg-amber-50 dark:bg-amber-900/20',
      description: t.interestDesc
    },
    {
      title: t.totalRepayment,
      value: formatCurrency(results.totalPayment, currency, lang),
      icon: <HandCoins className="text-blue-600 dark:text-blue-400" />,
      color: 'bg-blue-50 dark:bg-blue-900/20',
      description: t.repaymentDesc
    }
  ] : [
    {
      title: t.monthlyInstallment,
      value: formatCurrency(results.monthlyPayment, currency, lang),
      icon: <Wallet className="text-indigo-600 dark:text-indigo-400" />,
      color: 'bg-indigo-50 dark:bg-indigo-900/20',
      description: t.installmentDesc
    },
    {
      title: t.loanPrincipal,
      value: formatCurrency(results.totalPrincipal, currency, lang),
      icon: <Landmark className="text-emerald-600 dark:text-emerald-400" />,
      color: 'bg-emerald-50 dark:bg-emerald-900/20',
      description: t.principalDesc
    },
    {
      title: t.totalInterest,
      value: formatCurrency(results.totalInterest, currency, lang),
      icon: <Info className="text-amber-600 dark:text-amber-400" />,
      color: 'bg-amber-50 dark:bg-amber-900/20',
      description: t.interestDesc
    },
    {
      title: t.totalRepayment,
      value: formatCurrency(results.totalPayment, currency, lang),
      icon: <HandCoins className="text-blue-600 dark:text-blue-400" />,
      color: 'bg-blue-50 dark:bg-blue-900/20',
      description: t.repaymentDesc
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
      {cards.map((card, idx) => (
        <div key={idx} className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between transition-colors">
          <div className="flex justify-between items-start mb-4">
            <div className={`w-10 h-10 rounded-xl ${card.color} flex items-center justify-center`}>
              {card.icon}
            </div>
          </div>
          <div className={lang === Language.AR ? 'text-right' : ''}>
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{card.title}</p>
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{card.value}</h3>
          </div>
          <p className={`text-[10px] text-slate-400 dark:text-slate-500 mt-3 leading-tight ${lang === Language.AR ? 'text-right' : ''}`}>{card.description}</p>
        </div>
      ))}
    </div>
  );
};

export default SummaryCards;

import React from 'react';
import { 
  PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip,
  AreaChart, Area, XAxis, YAxis, CartesianGrid, BarChart, Bar
} from 'recharts';
import { LoanResults, Language, CalculationGoal } from '../types';
import { formatCurrency } from '../utils';
import { translations } from '../translations';

interface VisualizationsProps {
  results: LoanResults;
  currency: string;
  lang: Language;
  isDark: boolean;
  goal: CalculationGoal;
}

const Visualizations: React.FC<VisualizationsProps> = ({ results, currency, lang, isDark, goal }) => {
  const t = translations[lang];
  const labelColor = isDark ? '#94a3b8' : '#64748b';
  const gridColor = isDark ? '#1e293b' : '#f1f5f9';
  const tooltipBg = isDark ? '#0f172a' : '#ffffff';
  const tooltipBorder = isDark ? '#1e293b' : '#e2e8f0';

  if (goal === CalculationGoal.BUY_VS_RENT && results.buyVsRentComparison) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        <div className="flex flex-col h-[380px]">
          <h3 className={`text-sm font-semibold text-slate-700 dark:text-slate-300 mb-6 ${lang === Language.AR ? 'text-right' : ''}`}>{t.netWorthComp}</h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={results.buyVsRentComparison}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
                <XAxis 
                  dataKey="year" 
                  tick={{fontSize: 10, fill: labelColor}} 
                  tickLine={false} 
                  axisLine={false}
                  reversed={lang === Language.AR}
                />
                <YAxis 
                  tick={{fontSize: 10, fill: labelColor}} 
                  tickFormatter={(val) => `${val/1000}k`}
                  tickLine={false} 
                  axisLine={false}
                  orientation={lang === Language.AR ? 'right' : 'left'}
                />
                <Tooltip 
                  formatter={(value: number) => formatCurrency(value, currency, lang)}
                  contentStyle={{ backgroundColor: tooltipBg, borderRadius: '12px', border: `1px solid ${tooltipBorder}` }}
                />
                <Area type="monotone" dataKey="buyingNetWorth" stroke="#4f46e5" fill="#4f46e5" fillOpacity={0.1} name={t.buyerWealth} />
                <Area type="monotone" dataKey="rentingNetWorth" stroke="#f59e0b" fill="#f59e0b" fillOpacity={0.1} name={t.renterWealth} />
                <Legend />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col h-[380px]">
          <h3 className={`text-sm font-semibold text-slate-700 dark:text-slate-300 mb-6 ${lang === Language.AR ? 'text-right' : ''}`}>{t.unrecoverableComparison}</h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={results.buyVsRentComparison}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
                <XAxis 
                  dataKey="year" 
                  tick={{fontSize: 10, fill: labelColor}} 
                  tickLine={false} 
                  axisLine={false}
                  reversed={lang === Language.AR}
                />
                <YAxis 
                  tick={{fontSize: 10, fill: labelColor}} 
                  tickFormatter={(val) => `${val/1000}k`}
                  tickLine={false} 
                  axisLine={false}
                  orientation={lang === Language.AR ? 'right' : 'left'}
                />
                <Tooltip 
                  formatter={(value: number) => formatCurrency(value, currency, lang)}
                  contentStyle={{ backgroundColor: tooltipBg, borderRadius: '12px', border: `1px solid ${tooltipBorder}` }}
                />
                <Area type="monotone" dataKey="buyingUnrecoverable" stroke="#ef4444" fill="#ef4444" fillOpacity={0.1} name={t.buyingCosts} />
                <Area type="monotone" dataKey="rentingUnrecoverable" stroke="#64748b" fill="#64748b" fillOpacity={0.1} name={t.rentingCosts} />
                <Legend />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  }

  const pieData = [
    { name: t.principal, value: results.totalPrincipal, color: isDark ? '#6366f1' : '#4f46e5' },
    { name: t.interest, value: results.totalInterest, color: '#f59e0b' }
  ];

  const chartData = results.amortizationSchedule.filter((_, idx) => {
    if (results.amortizationSchedule.length <= 60) return true;
    return idx % Math.ceil(results.amortizationSchedule.length / 60) === 0;
  }).map(row => ({
    month: row.month,
    balance: Math.round(row.remainingBalance),
    paid: Math.round(results.totalPrincipal - row.remainingBalance)
  }));

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
      <div className="flex flex-col h-[380px]">
        <h3 className={`text-sm font-semibold text-slate-700 dark:text-slate-300 mb-6 ${lang === Language.AR ? 'text-right' : ''}`}>{t.repaymentComp}</h3>
        <div className="flex-1 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
                stroke="none"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip 
                formatter={(value: number) => formatCurrency(value, currency, lang)}
                contentStyle={{ 
                  backgroundColor: tooltipBg,
                  borderRadius: '12px', 
                  border: `1px solid ${tooltipBorder}`, 
                  boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                  color: isDark ? '#f1f5f9' : '#0f172a'
                }}
              />
              <Legend verticalAlign="bottom" height={36} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="flex flex-col h-[380px]">
        <h3 className={`text-sm font-semibold text-slate-700 dark:text-slate-300 mb-6 ${lang === Language.AR ? 'text-right' : ''}`}>{t.loanEvolution}</h3>
        <div className="flex-1 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorBalance" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={isDark ? '#6366f1' : '#4f46e5'} stopOpacity={0.2}/>
                  <stop offset="95%" stopColor={isDark ? '#6366f1' : '#4f46e5'} stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={gridColor} />
              <XAxis 
                dataKey="month" 
                tick={{fontSize: 10, fill: labelColor}} 
                tickLine={false} 
                axisLine={false}
                reversed={lang === Language.AR}
              />
              <YAxis 
                tick={{fontSize: 10, fill: labelColor}} 
                tickFormatter={(val) => `${val/1000}k`}
                tickLine={false} 
                axisLine={false}
                orientation={lang === Language.AR ? 'right' : 'left'}
              />
              <Tooltip 
                formatter={(value: number) => formatCurrency(value, currency, lang)}
                contentStyle={{ 
                  backgroundColor: tooltipBg,
                  borderRadius: '12px', 
                  border: `1px solid ${tooltipBorder}`, 
                  boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                  color: isDark ? '#f1f5f9' : '#0f172a'
                }}
              />
              <Area 
                type="monotone" 
                dataKey="balance" 
                stroke={isDark ? '#818cf8' : '#4f46e5'} 
                fillOpacity={1} 
                fill="url(#colorBalance)" 
                strokeWidth={2}
                name={t.remaining}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Visualizations;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { LoanInputs, LoanResults, Language } from '../types';
import { translations } from '../translations';
import { Sparkles, BrainCircuit, AlertCircle, TrendingUp, Info } from 'lucide-react';

interface AIAdvisorProps {
  inputs: LoanInputs;
  results: LoanResults;
  lang: Language;
}

const AIAdvisor: React.FC<AIAdvisorProps> = ({ inputs, results, lang }) => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const t = translations[lang];

  const generateInsight = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        As a world-class financial advisor, analyze this loan scenario and provide strategic advice in ${lang === 'ar' ? 'Arabic' : 'English'}.

        Scenario:
        - Goal: ${inputs.goal}
        - Principal: ${inputs.principal} ${inputs.currency}
        - Interest Rate: ${inputs.interestRate}% (${inputs.interestType})
        - Term: ${inputs.termMonths} months
        - Monthly Payment: ${results.monthlyPayment.toFixed(2)} ${inputs.currency}
        - Total Interest: ${results.totalInterest.toFixed(2)} ${inputs.currency}
        ${inputs.goal === 'BUY_VS_RENT' ? `- Rent: ${inputs.monthlyRent} ${inputs.currency} (Increase: ${inputs.rentIncrease}%)` : ''}
        ${inputs.goal === 'BUY_VS_RENT' ? `- Break-even: ${results.breakEvenYear ?? 'N/A'} years` : ''}

        Provide:
        1. A brief summary of the financial health of this deal.
        2. A strategic tip (e.g., if interest is high, suggest bi-weekly payments).
        3. A "Warning" if the DTI or unrecoverable costs seem excessive compared to alternatives.

        Format as clear Markdown with headers. Keep it concise.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setInsight(response.text || "No insight available.");
    } catch (error) {
      console.error(error);
      setInsight("Error consulting AI advisor. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-6">
      {!insight && !loading && (
        <div className="flex flex-col items-center justify-center py-12 px-6 text-center bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
          <div className="w-16 h-16 bg-indigo-100 dark:bg-indigo-900/30 rounded-2xl flex items-center justify-center text-indigo-600 mb-4 shadow-inner">
            <BrainCircuit size={32} />
          </div>
          <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{t.aiAdvisor}</h3>
          <p className="text-sm text-slate-500 dark:text-slate-400 max-w-sm mb-6">
            Get personalized financial strategy and risk assessment for this loan scenario using Gemini AI.
          </p>
          <button
            onClick={generateInsight}
            className="flex items-center gap-2 px-8 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl transition-all shadow-lg shadow-indigo-500/25 active:scale-95"
          >
            <Sparkles size={18} />
            {t.analyzeWithAI}
          </button>
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-24 gap-4">
          <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-sm font-medium text-indigo-600 animate-pulse">{t.aiThinking}</p>
        </div>
      )}

      {insight && (
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 shadow-xl shadow-indigo-500/5 animate-in fade-in duration-500">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <Sparkles className="text-indigo-600" size={20} />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white uppercase tracking-tight">{t.aiAdvisor}</h3>
            </div>
            <button 
              onClick={() => setInsight(null)}
              className="text-xs text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
            >
              Reset Analysis
            </button>
          </div>

          <div className={`prose prose-slate dark:prose-invert max-w-none text-sm leading-relaxed ${lang === 'ar' ? 'text-right' : 'text-left'}`}>
            <div className="whitespace-pre-wrap">
              {insight}
            </div>
          </div>

          <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800 grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl flex gap-3">
              <TrendingUp className="text-emerald-600 shrink-0" size={18} />
              <div>
                <p className="text-xs font-bold text-emerald-800 dark:text-emerald-400 uppercase tracking-wide">Key Insight</p>
                <p className="text-xs text-emerald-700 dark:text-emerald-300 mt-1">Based on current rates, this loan is considered moderately priced.</p>
              </div>
            </div>
            <div className="p-4 bg-amber-50 dark:bg-amber-900/10 rounded-2xl flex gap-3">
              <AlertCircle className="text-amber-600 shrink-0" size={18} />
              <div>
                <p className="text-xs font-bold text-amber-800 dark:text-amber-400 uppercase tracking-wide">Warning</p>
                <p className="text-xs text-amber-700 dark:text-amber-300 mt-1">Total interest exceeds 40% of principal. Consider a shorter term.</p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIAdvisor;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Calculator, 
  TrendingDown, 
  CircleDollarSign, 
  BarChart3, 
  TableProperties,
  ArrowRightLeft,
  Languages,
  BadgeDollarSign,
  Sun,
  Moon,
  Home,
  BrainCircuit,
  Settings2,
  ChevronRight,
  Info
} from 'lucide-react';
import { LoanInputs, InterestType, CalculationGoal, Language } from './types';
import { calculateLoan } from './utils';
import { translations } from './translations';
import SummaryCards from './components/SummaryCards';
import Visualizations from './components/Visualizations';
import AmortizationTable from './components/AmortizationTable';
import AIAdvisor from './components/AIAdvisor';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(Language.EN);
  const [isDark, setIsDark] = useState<boolean>(() => {
    if (typeof window !== 'undefined') {
      return window.matchMedia('(prefers-color-scheme: dark)').matches;
    }
    return false;
  });

  const t = translations[lang];

  const [inputs, setInputs] = useState<LoanInputs>({
    principal: 350000,
    interestRate: 5.8,
    termMonths: 360,
    interestType: InterestType.REDUCING,
    goal: CalculationGoal.INSTALLMENT,
    targetInstallment: 2200,
    currency: '$',
    monthlyRent: 1800,
    rentIncrease: 3.5,
    propertyAppreciation: 4.2,
    maintenancePercent: 1.1,
    investmentReturn: 7.5
  });

  const [activeTab, setActiveTab] = useState<'charts' | 'table' | 'ai'>('charts');

  const results = useMemo(() => calculateLoan(inputs), [inputs]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setInputs(prev => ({
      ...prev,
      [name]: (name === 'interestType' || name === 'goal' || name === 'currency') ? value : parseFloat(value) || 0
    }));
  };

  const toggleLang = () => {
    setLang(prev => prev === Language.EN ? Language.AR : Language.EN);
  };

  const toggleDarkMode = () => {
    setIsDark(!isDark);
  };

  useEffect(() => {
    document.documentElement.dir = lang === Language.AR ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [lang, isDark]);

  const isRTL = lang === Language.AR;

  return (
    <div className={`min-h-screen pb-20 transition-colors duration-300 bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 ${isRTL ? 'font-[Cairo,sans-serif]' : ''}`}>
      {/* Dynamic Background Elements */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden opacity-30 dark:opacity-20 z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500 rounded-full blur-[120px]" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-500 rounded-full blur-[120px]" />
      </div>

      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 sticky top-0 z-40 transition-all">
        <div className="max-w-7xl mx-auto px-4 lg:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-tr from-indigo-600 to-violet-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-500/20">
              <Calculator size={22} strokeWidth={2.5} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-slate-900 dark:text-white leading-tight tracking-tight">{t.title}</h1>
              <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold hidden sm:block">Intelligent Finance</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={toggleDarkMode}
              className="p-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-indigo-500 hover:text-white transition-all shadow-sm"
              aria-label="Toggle Dark Mode"
            >
              {isDark ? <Sun size={18} /> : <Moon size={18} />}
            </button>
            <button 
              onClick={toggleLang}
              className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-indigo-500 hover:text-white transition-all text-sm font-bold text-slate-600 dark:text-slate-300 shadow-sm"
            >
              <Languages size={18} />
              <span className="hidden sm:inline uppercase">{lang === Language.EN ? 'العربية' : 'EN'}</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 lg:px-6 mt-10 grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">

        {/* Sidebar - Controls */}
        <section className="lg:col-span-4 lg:sticky lg:top-24 flex flex-col gap-6">
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-800/50 p-8">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-xl font-bold flex items-center gap-3 text-slate-900 dark:text-white tracking-tight">
                <Settings2 size={22} className="text-indigo-600" />
                {t.configLoan}
              </h2>
              <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400">
                <Info size={14} />
              </div>
            </div>

            <div className="space-y-8">
              {/* Group: Goal */}
              <div className="bg-slate-50 dark:bg-slate-800/30 p-2 rounded-2xl">
                <div className="grid grid-cols-3 gap-1">
                  {[CalculationGoal.INSTALLMENT, CalculationGoal.LOAN_AMOUNT, CalculationGoal.BUY_VS_RENT].map((goal) => (
                    <button
                      key={goal}
                      onClick={() => setInputs(p => ({ ...p, goal }))}
                      className={`py-2.5 px-2 text-[10px] font-bold rounded-xl transition-all uppercase tracking-wide ${inputs.goal === goal ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm ring-1 ring-slate-200 dark:ring-slate-600' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}
                    >
                      {goal === CalculationGoal.INSTALLMENT ? t.calcPayment : goal === CalculationGoal.LOAN_AMOUNT ? t.findLoan : t.buyVsRent}
                    </button>
                  ))}
                </div>
              </div>

              {/* Group: Loan Basics */}
              <div className="space-y-5">
                <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-[0.2em]">{t.loanBasics}</h3>

                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2.5 flex items-center justify-between">
                    {inputs.goal === CalculationGoal.LOAN_AMOUNT ? t.targetPayment : t.loanAmount}
                    <span className="text-[10px] bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md text-slate-400 font-bold">{inputs.currency}</span>
                  </label>
                  <input
                    type="number"
                    name={inputs.goal === CalculationGoal.LOAN_AMOUNT ? "targetInstallment" : "principal"}
                    value={inputs.goal === CalculationGoal.LOAN_AMOUNT ? inputs.targetInstallment : inputs.principal}
                    onChange={handleInputChange}
                    className={`w-full px-5 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-[1.25rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all dark:text-white font-bold text-lg ${isRTL ? 'text-right' : ''}`}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-2.5 uppercase tracking-wider">{t.interestRate}</label>
                    <div className="relative">
                      <input
                        type="number"
                        step="0.1"
                        name="interestRate"
                        value={inputs.interestRate}
                        onChange={handleInputChange}
                        className={`w-full px-5 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none font-bold dark:text-white ${isRTL ? 'pr-5 pl-10 text-right' : 'pl-5 pr-10'}`}
                      />
                      <span className={`absolute ${isRTL ? 'left-4' : 'right-4'} top-1/2 -translate-y-1/2 text-slate-400 text-xs font-black`}>%</span>
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-2.5 uppercase tracking-wider">{t.termMonths}</label>
                    <div className="relative">
                      <input
                        type="number"
                        name="termMonths"
                        value={inputs.termMonths}
                        onChange={handleInputChange}
                        className="w-full px-5 py-3.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none font-bold dark:text-white"
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* Group: Rent Factors (Conditional) */}
              {inputs.goal === CalculationGoal.BUY_VS_RENT && (
                <div className="space-y-5 pt-4 border-t border-slate-100 dark:border-slate-800 animate-in slide-in-from-top-4 duration-300">
                  <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-[0.2em]">{t.compFactors}</h3>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-2.5 uppercase tracking-wider">{t.monthlyRent}</label>
                      <input
                        type="number"
                        name="monthlyRent"
                        value={inputs.monthlyRent}
                        onChange={handleInputChange}
                        className="w-full px-5 py-3.5 bg-indigo-50/30 dark:bg-indigo-900/10 border border-indigo-100 dark:border-indigo-900/30 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 outline-none font-bold dark:text-white"
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">{t.rentIncrease}</label>
                        <input
                          type="number"
                          step="0.1"
                          name="rentIncrease"
                          value={inputs.rentIncrease}
                          onChange={handleInputChange}
                          className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold dark:text-white"
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase">{t.appreciation}</label>
                        <input
                          type="number"
                          step="0.1"
                          name="propertyAppreciation"
                          value={inputs.propertyAppreciation}
                          onChange={handleInputChange}
                          className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-xs font-bold dark:text-white"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Strategy Group */}
              <div className="space-y-4">
                 <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-[0.2em]">{t.strategy}</h3>
                 <div className="grid grid-cols-2 gap-2 p-1 bg-slate-50 dark:bg-slate-800/30 rounded-xl">
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.REDUCING }))}
                    className={`py-3 px-2 text-[10px] font-bold rounded-xl flex flex-col items-center gap-1 transition-all ${inputs.interestType === InterestType.REDUCING ? 'bg-white dark:bg-slate-700 text-indigo-600 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 opacity-60'}`}
                  >
                    <TrendingDown size={14} /> {t.reducing}
                  </button>
                  <button
                    onClick={() => setInputs(p => ({ ...p, interestType: InterestType.FIXED }))}
                    className={`py-3 px-2 text-[10px] font-bold rounded-xl flex flex-col items-center gap-1 transition-all ${inputs.interestType === InterestType.FIXED ? 'bg-white dark:bg-slate-700 text-indigo-600 shadow-sm border border-slate-200 dark:border-slate-600' : 'text-slate-400 opacity-60'}`}
                  >
                    <ArrowRightLeft size={14} /> {t.fixed}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Content Area */}
        <section className="lg:col-span-8 flex flex-col gap-10">
          <SummaryCards results={results} currency={inputs.currency} lang={lang} goal={inputs.goal} />

          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-800 overflow-hidden flex-1 min-h-[600px] flex flex-col">
            <div className="flex border-b border-slate-100 dark:border-slate-800 p-2">
              <div className="flex bg-slate-100 dark:bg-slate-800/50 rounded-2xl p-1 w-full sm:w-auto">
                <button
                  onClick={() => setActiveTab('charts')}
                  className={`flex-1 sm:flex-none px-6 py-2.5 text-xs font-bold rounded-xl flex items-center justify-center gap-2 transition-all ${activeTab === 'charts' ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-md' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                  <BarChart3 size={16} /> {t.analysisCharts}
                </button>
                <button
                  onClick={() => setActiveTab('table')}
                  className={`flex-1 sm:flex-none px-6 py-2.5 text-xs font-bold rounded-xl flex items-center justify-center gap-2 transition-all ${activeTab === 'table' ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-md' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                  <TableProperties size={16} /> {t.amortSchedule}
                </button>
                <button
                  onClick={() => setActiveTab('ai')}
                  className={`flex-1 sm:flex-none px-6 py-2.5 text-xs font-bold rounded-xl flex items-center justify-center gap-2 transition-all ${activeTab === 'ai' ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-md' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                  <BrainCircuit size={16} /> {t.aiAdvisor}
                </button>
              </div>
            </div>

            <div className="p-8 flex-1 animate-in fade-in zoom-in-95 duration-500">
              {activeTab === 'charts' && (
                <Visualizations 
                  results={results} 
                  currency={inputs.currency} 
                  lang={lang} 
                  isDark={isDark} 
                  goal={inputs.goal}
                />
              )}
              {activeTab === 'table' && (
                <AmortizationTable 
                  schedule={results.amortizationSchedule} 
                  currency={inputs.currency} 
                  lang={lang} 
                />
              )}
              {activeTab === 'ai' && (
                <AIAdvisor 
                  inputs={inputs}
                  results={results}
                  lang={lang}
                />
              )}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { LoanResults, Language, CalculationGoal } from '../types';
import { formatCurrency } from '../utils';
import { translations } from '../translations';
import { Wallet, Landmark, HandCoins, Info, Clock, TrendingUp, ShieldCheck, Sparkles, AlertCircle } from 'lucide-react';

interface SummaryCardsProps {
  results: LoanResults;
  currency: string;
  lang: Language;
  goal: CalculationGoal;
}

const SummaryCards: React.FC<SummaryCardsProps> = ({ results, currency, lang, goal }) => {
  const t = translations[lang];
  const isRTL = lang === Language.AR;
  const isBuyVsRent = goal === CalculationGoal.BUY_VS_RENT;

  const cards = isBuyVsRent ? [
    {
      title: t.monthlyInstallment,
      value: formatCurrency(results.monthlyPayment, currency, lang),
      icon: <Wallet className="text-indigo-600" size={20} />,
      color: 'bg-indigo-50 dark:bg-indigo-500/10',
      description: t.installmentDesc,
      priority: true
    },
    {
      title: t.buyVsRent,
      value: results.breakEvenYear ? `${t.betterToBuy} ${results.breakEvenYear} ${t.yrs}` : t.betterToRent,
      icon: results.breakEvenYear ? <ShieldCheck className="text-emerald-600" size={20} /> : <AlertCircle className="text-rose-600" size={20} />,
      color: results.breakEvenYear ? 'bg-emerald-50 dark:bg-emerald-500/10' : 'bg-rose-50 dark:bg-rose-500/10',
      description: t.rentDesc,
      badge: results.breakEvenYear ? 'Buy' : 'Rent'
    },
    {
      title: t.totalInterest,
      value: formatCurrency(results.totalInterest, currency, lang),
      icon: <Info className="text-amber-600" size={20} />,
      color: 'bg-amber-50 dark:bg-amber-500/10',
      description: t.interestDesc
    },
    {
      title: t.totalRepayment,
      value: formatCurrency(results.totalPayment, currency, lang),
      icon: <HandCoins className="text-blue-600" size={20} />,
      color: 'bg-blue-50 dark:bg-blue-500/10',
      description: t.repaymentDesc
    }
  ] : [
    {
      title: t.monthlyInstallment,
      value: formatCurrency(results.monthlyPayment, currency, lang),
      icon: <Wallet className="text-indigo-600" size={20} />,
      color: 'bg-indigo-50 dark:bg-indigo-500/10',
      description: t.installmentDesc,
      priority: true
    },
    {
      title: t.loanPrincipal,
      value: formatCurrency(results.totalPrincipal, currency, lang),
      icon: <Landmark className="text-emerald-600" size={20} />,
      color: 'bg-emerald-50 dark:bg-emerald-500/10',
      description: t.principalDesc
    },
    {
      title: t.totalInterest,
      value: formatCurrency(results.totalInterest, currency, lang),
      icon: <Info className="text-amber-600" size={20} />,
      color: 'bg-amber-50 dark:bg-amber-500/10',
      description: t.interestDesc
    },
    {
      title: t.totalRepayment,
      value: formatCurrency(results.totalPayment, currency, lang),
      icon: <HandCoins className="text-blue-600" size={20} />,
      color: 'bg-blue-50 dark:bg-blue-500/10',
      description: t.repaymentDesc
    }
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
      {cards.map((card, idx) => (
        <div 
          key={idx} 
          className={`group relative bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-200/40 dark:shadow-none flex flex-col justify-between transition-all hover:translate-y-[-4px] hover:shadow-indigo-500/10 ${card.priority ? 'ring-2 ring-indigo-500 ring-offset-4 ring-offset-slate-50 dark:ring-offset-slate-950' : ''}`}
        >
          {card.badge && (
            <div className={`absolute top-4 ${isRTL ? 'left-4' : 'right-4'} text-[8px] font-black uppercase px-2 py-1 rounded-full ${card.badge === 'Buy' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
              {card.badge}
            </div>
          )}

          <div className="flex justify-between items-start mb-6">
            <div className={`w-12 h-12 rounded-2xl ${card.color} flex items-center justify-center shadow-inner transition-transform group-hover:scale-110`}>
              {card.icon}
            </div>
          </div>

          <div className={isRTL ? 'text-right' : 'text-left'}>
            <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{card.title}</p>
            <h3 className={`font-black text-slate-900 dark:text-white leading-none tracking-tight transition-all ${card.priority ? 'text-2xl sm:text-3xl' : 'text-xl sm:text-2xl'}`}>
              {card.value}
            </h3>
          </div>

          <p className={`text-[9px] font-medium text-slate-400 dark:text-slate-600 mt-4 leading-tight ${isRTL ? 'text-right' : 'text-left'}`}>
            {card.description}
          </p>
        </div>
      ))}
    </div>
  );
};

export default SummaryCards;

import React, { useState } from 'react';
import { AmortizationRow, Language } from '../types';
import { formatCurrency } from '../utils';
import { translations } from '../translations';
import { ChevronLeft, ChevronRight, ArrowDownToLine } from 'lucide-react';

interface AmortizationTableProps {
  schedule: AmortizationRow[];
  currency: string;
  lang: Language;
}

const AmortizationTable: React.FC<AmortizationTableProps> = ({ schedule, currency, lang }) => {
  const t = translations[lang];
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 12; 

  const totalPages = Math.ceil(schedule.length / rowsPerPage);
  const currentRows = schedule.slice((currentPage - 1) * rowsPerPage, currentPage * rowsPerPage);

  const isRTL = lang === Language.AR;

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 overflow-x-auto custom-scrollbar">
        <table className={`w-full text-sm ${isRTL ? 'text-right' : 'text-left'} border-separate border-spacing-0`}>
          <thead className="sticky top-0 z-20">
            <tr className="bg-slate-50 dark:bg-slate-800">
              <th className={`px-6 py-4 font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-[10px] border-b border-slate-100 dark:border-slate-700 ${isRTL ? 'rounded-tr-2xl' : 'rounded-tl-2xl'}`}>
                {t.month}
              </th>
              <th className="px-6 py-4 font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-[10px] border-b border-slate-100 dark:border-slate-700">
                {t.monthlyInstallment}
              </th>
              <th className="px-6 py-4 font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-[10px] border-b border-slate-100 dark:border-slate-700">
                {t.principal}
              </th>
              <th className="px-6 py-4 font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-[10px] border-b border-slate-100 dark:border-slate-700">
                {t.interest}
              </th>
              <th className={`px-6 py-4 font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest text-[10px] border-b border-slate-100 dark:border-slate-700 ${isRTL ? 'rounded-tl-2xl' : 'rounded-tr-2xl'}`}>
                {t.remaining}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
            {currentRows.map((row) => (
              <tr key={row.month} className="group hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-all duration-200">
                <td className="px-6 py-5 font-black text-slate-400 dark:text-slate-600 text-xs">
                  {row.month}
                </td>
                <td className="px-6 py-5 text-slate-900 dark:text-white font-bold">
                  {formatCurrency(row.payment, currency, lang)}
                </td>
                <td className="px-6 py-5 text-emerald-600 dark:text-emerald-400 font-medium">
                  {formatCurrency(row.principal, currency, lang)}
                </td>
                <td className="px-6 py-5 text-amber-600 dark:text-amber-400 font-medium">
                  {formatCurrency(row.interest, currency, lang)}
                </td>
                <td className="px-6 py-5">
                  <span className="bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-xl font-black text-slate-900 dark:text-white text-xs shadow-sm">
                    {formatCurrency(row.remainingBalance, currency, lang)}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className={`flex flex-col sm:flex-row items-center justify-between mt-8 pt-8 border-t border-slate-100 dark:border-slate-800 gap-4 ${isRTL ? 'sm:flex-row-reverse' : ''}`}>
        <p className="text-xs font-bold text-slate-400 dark:text-slate-600 uppercase tracking-widest">
          {t.showingYear} {currentPage} {t.of} {Math.ceil(totalPages)}
        </p>

        <div className="flex items-center gap-3">
          <button
            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
            disabled={currentPage === 1}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-100 dark:bg-slate-800 disabled:opacity-30 hover:bg-indigo-500 hover:text-white transition-all text-xs font-bold text-slate-600 dark:text-slate-400 shadow-sm"
          >
            {isRTL ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
          </button>

          <div className="flex gap-1">
            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
               // Simple logic to show some page numbers
               const pageNum = i + 1;
               return (
                 <button
                  key={pageNum}
                  onClick={() => setCurrentPage(pageNum)}
                  className={`w-8 h-8 rounded-lg text-[10px] font-black transition-all ${currentPage === pageNum ? 'bg-indigo-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}
                 >
                   {pageNum}
                 </button>
               )
            })}
          </div>

          <button
            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
            disabled={currentPage === totalPages}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-100 dark:bg-slate-800 disabled:opacity-30 hover:bg-indigo-500 hover:text-white transition-all text-xs font-bold text-slate-600 dark:text-slate-400 shadow-sm"
          >
            {isRTL ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AmortizationTable;
